    if (host && (!/^([a-z0-9-]+\.)+[a-z]{2,}$/.test(host) || /(^|\.)studioflowandsystems\.(app|com)$/.test(host))) return secJson({ ok: false, error: "That isn't a client web address." }, 400);
    const raw = await secGet(env, "instance").catch(() => null) || {};
